#!/usr/bin/env python3
"""Regenerate docs/BENCHMARKS.md from the benchmark table.

Keeping the document generated means the prose can never drift from the values
the analysis actually uses.

    python scripts/gen_benchmark_docs.py
"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))

from jevbench.benchmarks import BENCHMARKS  # noqa: E402

HEADER = """# Human benchmarks

<!-- Generated by scripts/gen_benchmark_docs.py — do not edit by hand. -->

Reference values from the published literature, used to give the model's
numbers a human scale.

## Read this before comparing anything

These are **not a matched control group.** Each value comes from a different
published sample, with its own population, stake size, currency, decade and lab
protocol. None of the humans behind these numbers answered the items in this
repository, and none answered them under the conditions the model did.

What that means in practice:

- A gap of a few points is **not** interpretable. Do not read one.
- Only large, directional divergences support a claim.
- Where a human result is a *contrast* rather than a level — the framing
  reversal, the anchoring gap, the present-bias flip — the contrast is the
  robust quantity and the levels are not. Compare contrasts.

The `reliability` column is deliberately conservative:

| Flag | Meaning |
|---|---|
| `high` | large meta-analysis, or a very widely replicated single finding |
| `medium` | well known, but point estimates move across samples |
| `approximate` | order of magnitude only; strongly sample-dependent |

"""


def main() -> int:
    rows = sorted(BENCHMARKS.values(), key=lambda b: (b.reliability != "high", b.key))
    lines = [HEADER, "## Values\n"]
    lines.append("| Benchmark | Statistic | Value | Units | Reliability |")
    lines.append("|---|---|---:|---|---|")
    for b in rows:
        lines.append(
            f"| `{b.key}` | {b.statistic} | {b.value:g} | {b.units} | {b.reliability} |"
        )
    lines.append("\n## Sources and caveats\n")
    for b in rows:
        lines.append(f"**`{b.key}`** — {b.statistic}\n")
        lines.append(f"- Value: {b.value:g} {b.units} ({b.reliability})")
        lines.append(f"- Source: {b.source}")
        if b.note:
            lines.append(f"- Note: {b.note}")
        lines.append("")
    out = ROOT / "docs" / "BENCHMARKS.md"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {out} ({len(rows)} benchmarks)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
